  "a_sentences": [
    {
      "a_text": "P1: Les sous-locataires B.B.________ et son conjoint ne disposent pas de droit à l'encontre de la bailleresse, car ils ne sont pas liés contractuellement avec elle.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2: Lorsque le bailleur résilie le bail après le décès du locataire, il doit notifier le congé à tous les héritiers, sous peine de nullité.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3: Pour un logement de famille, le congé doit être communiqué séparément au locataire et à son conjoint ou partenaire enregistré.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4: B.B.________, en tant que sous-locataire de feu son père, ne peut pas s'opposer à la résiliation du bail principal, et son mari ne bénéficie pas de la protection de l'art. 266n CO.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5: Le conjoint de la membre de l'hoirie locataire n'est pas au bénéfice de la prescription de forme du congé de l'art. 266n CO, même si le logement sert de logement de famille.",
      "b_propositions": ["P5"]
    }
  ]
}
